import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"PX4 Flight Modes Setup","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/setup_view/flight_modes_px4.md","filePath":"en/qgc-user-guide/setup_view/flight_modes_px4.md"}`),a={name:`en/qgc-user-guide/setup_view/flight_modes_px4.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="px4-flight-modes-setup" tabindex="-1">PX4 Flight Modes Setup <a class="header-anchor" href="#px4-flight-modes-setup" aria-label="Permalink to “PX4 Flight Modes Setup”">​</a></h1><p>The <em>Flight Modes</em> section allows you to configure which <a href="http://docs.px4.io/main/en/getting_started/flight_modes.html" target="_blank" rel="noreferrer">flight modes</a> and other actions are triggered by particular switches/switch positions on your RC transmitter.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>In order to set up flight modes you must already have</p><ul><li><a href="./../setup_view/radio.html">Configured your radio</a> in order to set flight modes.</li><li><a href="./flight_modes.html#transmitter-setup">Setup the RC transmitter</a> (Flight Modes &gt; Transmitter Setup) :::</li></ul><p>To access this section, select the <strong>Gear</strong> icon (Vehicle Setup) in the top toolbar and then <strong>Flight Modes</strong> in the sidebar.</p><p>The page only shows settings the connected vehicle has, and only those that apply to its type. It is designed for PX4 1.17 or later. Older firmware shows only the settings it has. The choices, units and limits of each setting come from the vehicle&#39;s parameter metadata. Changes are written to the vehicle immediately.</p><p>The top of the page shows the manual control source (<code>COM_RC_IN_MODE</code>). When it does not use RC input, the mode channel and switches have no effect. A warning also appears when two functions on the same RC channel can be on at the same time, such as a switch on a stick channel, or two switches with the same threshold. Two switches can share a channel when their thresholds split it, for example one on when the switch is low and the other when it is high.</p><h2 id="mode-selection" tabindex="-1">Mode Selection <a class="header-anchor" href="#mode-selection" aria-label="Permalink to “Mode Selection”">​</a></h2><ul><li><p><strong>Selection method</strong> — how the pilot selects one of six mode slots:</p><ul><li><strong>Switch channel</strong>: the position of one channel (<code>RC_MAP_FLTMODE</code>) selects the slot.</li><li><strong>Buttons</strong>: each momentary button channel (<code>RC_MAP_FLTM_BTN</code>) selects a slot, lowest channel first. PX4 uses up to six.</li><li><strong>None</strong>: modes are not selected from RC.</li></ul><p>PX4 ignores the buttons while a mode channel is set, so choosing a method clears the other.</p></li><li><p><strong>Mode slots</strong> — the flight mode for each slot (<code>COM_FLTMODE1</code> to <code>COM_FLTMODE6</code>). With a switch channel, each slot shows its PWM range and a live bar shows where the channel is. With buttons, each slot shows its button channel. The active slot is highlighted. External modes are shown by the name the vehicle reports for them. External mode slots with no mode registered are not offered, unless the slot is already selected, when it is marked <em>not running</em>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Position mode, return mode and mission mode <a href="https://docs.px4.io/main/en/config/flight_mode.html#what-flight-modes-and-switches-should-i-set" target="_blank" rel="noreferrer">are recommended</a>.</p></div></li><li><p><strong>Mode on boot</strong> — the mode set at power-up (PX4 1.18 and later).</p></li></ul><h2 id="switches" tabindex="-1">Switches <a class="header-anchor" href="#switches" aria-label="Permalink to “Switches”">​</a></h2><p>Channels that trigger particular actions, such as <em>Return</em>, <em>Kill</em> or landing gear. Each switch shows its channel and threshold, and the live switch position once it is assigned. The threshold is a fraction of the channel range: the switch is on above it, or below it when the threshold is negative. <em>Flight termination</em> cannot be undone until the vehicle reboots.</p><h2 id="stick-gestures-position-slow-mode-and-pilot-takeover" tabindex="-1">Stick Gestures, Position Slow Mode and Pilot Takeover <a class="header-anchor" href="#stick-gestures-position-slow-mode-and-pilot-takeover" aria-label="Permalink to “Stick Gestures, Position Slow Mode and Pilot Takeover”">​</a></h2><ul><li><strong>Stick Gestures</strong> — arming and disarming with the sticks, and the kill gesture.</li><li><strong>Position Slow Mode</strong> — speed limits for multicopter Position Slow mode, and the AUX knobs that scale a speed in flight from its minimum up to the normal manual limit. The speed limits apply when no knob is assigned.</li><li><strong>Pilot Takeover</strong> — the stick override that switches an automatic mode to Position when the pilot moves the sticks.</li></ul><p>Select <strong>Assigned</strong> to hide switches and options that are not in use.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to “Testing”">​</a></h2><ol><li>Turn on your RC transmitter.</li><li>If a switch does not seem to respond, check on the <a href="./../setup_view/radio.html">Radio</a> page that it moves the expected channel.</li><li>Select each mode switch position or button in turn, and check that the expected slot is highlighted. Assigned switches show <em>On</em> or <em>Off</em> as they are moved.</li></ol><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to “See Also”">​</a></h2><ul><li><a href="https://docs.px4.io/main/en/flight_modes/" target="_blank" rel="noreferrer">PX4 Flight Modes</a></li></ul></div>`,3)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};